/* package codechef; // don't place package name! */

import java.util.*;
import java.lang.*;
import java.io.*;

/* Name of the class has to be "Main" only if the class is public. */
public class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int b=sc.nextInt();
		int array[]=new int[n];
		int cost[]=new int[n];
		Arrays.fill(cost,-1);
		for(int i=0;i<n;i++){
		    array[i]=sc.nextInt();
		}

		int co=0,ce=0,cut=0,coin=0;
		for(int i=0;i<n;i++){
		    if(array[i]%2==0){ce+=1;}
		    else{co+=1;}
            if(co==ce && i!=array.length-1){
                if(i!=(array.length-1)){cost[i]=Math.abs(array[i+1]-array[i]);}
                co=0;ce=0;
            }
		}
	    Arrays.sort(cost);
	    int sum=0;
		for(int i=0;i<cost.length;i++){
		    if(cost[i]!=-1){
		    sum=sum+cost[i];
		    if(sum>b){break;}

		    cut+=1;}
		}
		System.out.println(cut);
	}
}

